INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Daten immer strukturiert?', 2, '[{"text": "Nein", "correct": true, "because": "Unstrukturierte Daten wie Bilder existieren"}, {"text": "Ja", "correct": false, "because": "Verschiedene Formen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Verwaltung von Daten?', 3, '[{"text": "Informationen nutzbar machen", "correct": true, "because": "Daten werden zugänglich"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Ziel"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Daten gibt es?', 5, '[{"text": "Strukturierte", "correct": true, "because": "Tabellenform"}, {"text": "Unstrukturierte", "correct": true, "because": "z. B. Videos"}, {"text": "Physische", "correct": false, "because": "Kein Datentyp"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daten können digital gespeichert werden. b) Sie sind immer sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sichtbarkeit abhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Daten?', 4, '[{"text": "Integrität", "correct": false, "because": "Sichert Konsistenz"}, {"text": "Speicherort", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Bildschirmfarbe", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob alle Daten digital sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch analoge Daten existieren"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaft beschreibt Daten?', 3, '[{"text": "Format", "correct": true, "because": "Bestimmt Struktur"}, {"text": "Gewicht", "correct": false, "because": "Kein physisches Merkmal"}, {"text": "Farbe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen kann ich mit Daten durchführen?', 5, '[{"text": "Speichern", "correct": true, "because": "Dauerhafte Ablage"}, {"text": "Analysieren", "correct": true, "because": "Erkenntnisse gewinnen"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Datenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Daten haben Metadaten. b) Sie sind immer verschlüsselt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Datenverwaltung?', 4, '[{"text": "Speichermedium", "correct": false, "because": "Datenablage nötig"}, {"text": "Software", "correct": false, "because": "Verarbeitung erforderlich"}, {"text": "Kaffeemaschine", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Daten dasselbe wie Informationen?', 2, '[{"text": "Nein", "correct": true, "because": "Daten werden zu Informationen verarbeitet"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Datenquellen gibt es?', 4, '[{"text": "Datenbanken", "correct": true, "because": "Strukturierte Quelle"}, {"text": "Sensoren", "correct": true, "because": "Echtzeitdaten"}, {"text": "Monitorgröße", "correct": false, "because": "Kein Datenlieferant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Daten immer sicher sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Sicherheit muss gewährleistet werden"}, {"text": "Ja", "correct": false, "because": "Risiken existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenverarbeitung?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Schützt vor Verlust"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Daten können analysiert werden. b) Sie sind immer physisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Physisch nicht zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools nutze ich für Daten?', 5, '[{"text": "Datenbanken", "correct": true, "because": "Strukturierte Verwaltung"}, {"text": "Analyse-Software", "correct": true, "because": "Erkenntnisse gewinnen"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein Datenfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Datenverwaltung unwichtig?', 3, '[{"text": "Backup", "correct": false, "because": "Schützt vor Verlust"}, {"text": "Zugriffskontrolle", "correct": false, "because": "Sichert Daten"}, {"text": "Tastaturdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Daten immer statisch?', 3, '[{"text": "Nein", "correct": true, "because": "Können dynamisch sein"}, {"text": "Ja", "correct": false, "because": "Änderungen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Daten nur in Dateien liegen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Datenbanken"}, {"text": "Ja", "correct": false, "because": "Verschiedene Speicherorte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Format bei Daten?', 4, '[{"text": "Bestimmt Verarbeitung", "correct": true, "because": "Struktur entscheidend"}, {"text": "Erhöht Speicher", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Ändert Hardware", "correct": false, "because": "Irrelevant"}]');
